import { createApi } from '@reduxjs/toolkit/query/react';

import { bffBaseQuery } from './bffBaseQuery';

export const bffApi = createApi({
  reducerPath: 'bffApi',
  baseQuery: bffBaseQuery,
  tagTypes: ['BffView'],
  endpoints: () => ({}),
});
